// =====================================================================
// ARMAR PAYLOAD PARA GEMINI CON CONTEXTO REAL DEL CRM
// =====================================================================
const body = $input.first().json.body || $input.first().json;
const textoCliente = (body.content || body.texto || '').toString().trim();
const lead = body.lead || {};
const paso = body.conversationStep || 1; // Estado de la conversación enviado desde el HTML

const nombre = lead.primerNombre || lead.contacto || 'Contacto';
const empresa = lead.empresa || 'la empresa';
const sistema = lead.sistema || 'su sistema ERP';
const facturas = lead.facturas || '400';
const motivo = lead.motivo || 'cambio de sistema';

const systemPrompt = `Sos un ejecutivo comercial de Xtract (xtract.app). Tu objetivo es reactivar la conversación profesional con ${nombre} de la empresa ${empresa}.

FICHA DEL CLIENTE:
- Nombre: ${nombre}
- Empresa: ${empresa}
- Sistema ERP: ${sistema}
- Facturas mensuales: ${facturas}
- Motivo registrado: "${motivo}"

TONO Y ESTILO (MANDATORIO B2B):
- Tono corporativo, profesional, educado y respetuoso.
- ESTRICTAMENTE PROHIBIDO usar expresiones coloquiales (NUNCA: "renegando", "dale", "en un toque", "chatear").
- Lenguaje ejecutivo impecable adecuado para directores de administración y finanzas.
- Respuestas cortas: máximo 2 oraciones. Sin emojis.

ESTADO ACTUAL DE LA CONVERSACIÓN: PASO ${paso}

${paso === 1 || paso === '1' ? `PASO 1 — PROPUESTA DE REUNIÓN:
- El cliente acaba de responder al template inicial: "Hola ${nombre}, ¿cómo estás? Te escribo de parte del equipo de Xtract."
- Tu objetivo es retomar el vínculo comercial y proponer una reunión de 10 minutos.
- Respondé en 2 oraciones mencionando el contexto (empresa, ERP) y preguntando si les sirve una llamada de 10 minutos.
- NUNCA incluyas la palabra "Calendly" en este paso. NO agendes todavía.` : ''}

${paso === 2 || paso === '2' ? `PASO 2 — CONFIRMACIÓN DE AGENDA:
- Ya propusiste la reunión de 10 minutos. El cliente acaba de responder a esa propuesta.
- Si acepta ("sí", "dale", "me sirve", "perfecto", "claro", "agendo", "agendar"):
  Respondé: "Excelente ${nombre}. Le comparto la opción para agendar la reunión en Calendly según la disponibilidad de su agenda:"
  (incluye la palabra CALENDLY para activar el card automáticamente)
- Si no acepta claramente: despedite formalmente sin insistir.` : ''}

REGLAS DE SEGURIDAD (APLICAN EN CUALQUIER PASO):
- PREGUNTAS TÉCNICAS COMPLEJAS (APIs, código, SQL, impuestos específicos, AGIP, ARBA, SICORE, integración custom):
  Respondé: "Esa consulta requiere la atención de un especialista de nuestro equipo de ingeniería. Les derivamos la conversación y se comunicarán a la brevedad."
  (incluye la palabra ESPECIALISTA en tu respuesta)
- SERVICIOS FUERA DEL ALCANCE DE XTRACT: Aclarar que Xtract se especializa exclusivamente en automatización de carga contable y facturación.
- RECHAZO EXPLÍCITO: Agradecer y despedirse formalmente.`;

const geminiBody = {
  systemInstruction: {
    parts: [{ text: systemPrompt }]
  },
  contents: [
    {
      role: "model",
      parts: [{ text: `Hola ${nombre}, ¿cómo estás? Te escribo de parte del equipo de Xtract.` }]
    },
    {
      role: "user",
      parts: [{ text: textoCliente }]
    }
  ],
  generationConfig: {
    temperature: 0.3,
    maxOutputTokens: 2048
  }
};

return {
  json: {
    geminiPayload: geminiBody,
    textoCliente: textoCliente,
    lead: lead,
    paso: paso
  }
};

let respuestaIA = '';
try {
  const res = $input.first().json;
  if (res.candidates && res.candidates[0] && res.candidates[0].content) {
    // Gemini respondió correctamente
    respuestaIA = res.candidates[0].content.parts[0].text || '';
  } else {
    // --- FALLBACK LOCAL (API key expirada o sin créditos) ---
    const ctx = $node['Armar Contexto y Prompt Gemini'].json;
    const lead = ctx.lead || {};
    const nombre = lead.primerNombre || 'Gabriela';
    const sistema = lead.sistema || 'SOFTLAND';
    const empresa = lead.empresa || 'la empresa';
    const facturas = lead.facturas || '400';
    const paso = parseInt(ctx.paso) || 1;
    const txt = (ctx.textoCliente || '').toLowerCase();

    // --- RECHAZO (cualquier paso) ---
    const rechaza = txt.includes('no gracias') || txt.includes('no me interesa') ||
                    txt.includes('ya contratamos') || txt.includes('ya no trabajo') ||
                    txt.includes('no es el momento') || txt.includes('no estamos interesados');
    if (rechaza) {
      respuestaIA = `Muchas gracias por responder, ${nombre}. Dejamos asentada la novedad en nuestro sistema. Saludos cordiales.`;
    }
    // --- ESCALACIÓN TÉCNICA A CHATWOOT (cualquier paso) ---
    else if (
      txt.includes('api') || txt.includes('webhook') || txt.includes('sql') ||
      txt.includes('script') || txt.includes('código') || txt.includes('codigo') ||
      txt.includes('agip') || txt.includes('arba') || txt.includes('arca') || txt.includes('sicore') ||
      txt.includes('retención') || txt.includes('retencion') || txt.includes('percepción') ||
      txt.includes('base de datos') || txt.includes('integracion custom') || txt.includes('integración custom') ||
      txt.includes('desarrollo') || txt.includes('programar')
    ) {
      respuestaIA = `Esa consulta requiere la atención de un especialista de nuestro equipo de ingeniería. Les derivamos la conversación y se comunicarán a la brevedad.`;
    }
    // --- PASO 1: Primera respuesta — explicar Xtract o hacer la propuesta de reunión ---
    else if (paso === 1) {
      if (txt.includes('qué es') || txt.includes('que es') || txt.includes('de qué') || txt.includes('de que') || txt.includes('cómo funciona') || txt.includes('como funciona') || txt.includes('xtract')) {
        respuestaIA = `Xtract automatiza la lectura y carga contable de facturas directamente en ${sistema}, eliminando la carga manual. ¿Les resultaría útil revisarlo 10 minutos en una llamada para ver el impacto concreto en ${empresa}?`;
      } else if (txt.includes('precio') || txt.includes('cuánto') || txt.includes('cuanto') || txt.includes('plan') || txt.includes('costo') || txt.includes('caro')) {
        respuestaIA = `Trabajamos con planes escalables según el volumen de facturación. Con las ${facturas} facturas mensuales de ${empresa}, el impacto sería significativo. ¿Les resultaría útil revisarlo 10 minutos en una llamada para ver los números concretos?`;
      } else if (txt.includes('tango') || txt.includes('softland') || txt.includes('sistema') || txt.includes('erp') || txt.includes('cambio')) {
        respuestaIA = `Justamente por eso nos comunicamos, ${nombre}. Incorporamos mejoras en la integración nativa con ${sistema} que permiten automatizar la carga contable sin modificar su configuración actual. ¿Les resultaría útil revisarlo 10 minutos en una llamada?`;
      } else {
        respuestaIA = `Hace un tiempo estuvimos en contacto porque desde ${empresa} buscaban optimizar la carga contable en ${sistema}. Te escribía para consultar si ya lograron resolver ese punto o si les resulta útil que lo revisemos 10 minutos en una llamada.`;
      }
    }
    // --- PASO 2: El prospecto responde a la propuesta de reunión ---
    else if (paso === 2) {
      const tieneDia = txt.includes('lunes') || txt.includes('martes') || txt.includes('miércoles') || txt.includes('miercoles') ||
                       txt.includes('jueves') || txt.includes('viernes') || txt.includes('mañana') || txt.includes('tarde') ||
                       txt.includes('semana');

      const acepta = tieneDia || txt.includes('sí') || txt.includes('si') || txt.includes('dale') ||
                     txt.includes('bueno') || txt.includes('claro') || txt.includes('perfecto') ||
                     txt.includes('agendar') || txt.includes('reunión') || txt.includes('reunion') ||
                     txt.includes('me sirve') || txt.includes('me gustaría') || txt.includes('me gustaria') ||
                     txt.includes('mostrame') || txt.includes('adelante') || txt.includes('ok');

      const esSaludo = txt.includes('hola') || txt.includes('buenas') || txt.includes('qué tal') || txt.includes('que tal');

      if (tieneDia) {
        respuestaIA = `Excelente ${nombre}. Para el día solicitado tengo estos horarios disponibles en horario de Argentina:\n1) 09:30 hs\n2) 11:00 hs\n3) 14:30 hs\n¿Cuál te queda mejor y nos confirmás tu correo para enviarte la invitación por Calendly?`;
      } else if (acepta) {
        const opts = [
          `Excelente ${nombre}. Le comparto la opción para agendar la reunión en Calendly según la disponibilidad de su agenda:`,
          `Perfecto ${nombre}. Le dejo la opción para coordinar la reunión de 10 minutos a través de Calendly:`,
          `Muy bien. Le adjunto el enlace de Calendly para agendar en el horario que le resulte más conveniente:`
        ];
        respuestaIA = opts[Math.floor(Math.random() * opts.length)];
      } else if (txt.includes('qué es') || txt.includes('que es') || txt.includes('de qué') || txt.includes('de que') || txt.includes('cómo') || txt.includes('xtract')) {
        respuestaIA = `Xtract automatiza la lectura y carga contable de facturas en ${sistema}, ahorrando más del 70% del tiempo de ingreso manual. ¿Les parece si lo revisamos 10 minutos en una llamada esta semana?`;
      } else if (esSaludo) {
        respuestaIA = `Hola ${nombre}. Te consultaba si a desde ${empresa} les resultaría útil coordinar una breve llamada de 10 minutos para revisar las novedades sobre ${sistema}.`;
      } else {
        respuestaIA = `Te consultaba ${nombre} si les sirve coordinar 10 minutos esta semana para revisar cómo optimizar la carga contable en ${sistema}. ¿Te queda bien en algún horario?`;
      }
    }
    // --- PASO 3+: Ya agendó ---
    else {
      respuestaIA = `Quedamos coordinados, ${nombre}. Nos vemos en la llamada. ¡Hasta pronto!`;
    }
  }
} catch(e) {
  respuestaIA = 'Hola. Te escribía para consultar si lograron resolver la carga contable. ¿Les resulta útil que lo revisemos 10 minutos en una llamada?';
}

return {
  json: {
    response: respuestaIA
  }
};
